func (c *Core) cdlmatholdOpenAndFillInternal(inOpen, inHigh, inLow, inClose []float64, startIdx int32, optInPenetration float64, outBegIdx, outNBElement *int32, outInteger []int32) (*CDLMATHOLDStream, error) {
	sp := &CDLMATHOLDStream{core: c}
	if retCode := c.cdlmatholdOpenImpl(sp, inOpen, inHigh, inLow, inClose, startIdx, optInPenetration, outBegIdx, outNBElement, outInteger, 1); retCode != Success {
		return nil, retCode
	}
	sp.outRangeBegIdx = int(*outBegIdx)
	sp.outRangeCount = int(*outNBElement)
	return sp, nil
}

func (c *Core) cdlmatholdOpenInternal(inOpen, inHigh, inLow, inClose []float64, startIdx int32, optInPenetration float64) (*CDLMATHOLDStream, error) {
	sp := &CDLMATHOLDStream{core: c}
	var outBegIdx, outNBElement int32
	var sink_outInteger [1]int32
	if retCode := c.cdlmatholdOpenSinkFrame(sp, inOpen, inHigh, inLow, inClose, startIdx, optInPenetration, &outBegIdx, &outNBElement, sink_outInteger[:]); retCode != Success {
		return nil, retCode
	}
	sp.outRangeBegIdx = int(outBegIdx)
	sp.outRangeCount = int(outNBElement)
	return sp, nil
}

// CDLMATHOLDOpen opens a live [CDLMATHOLDStream] on a warm-up history, oldest
// bar first, and returns it with its value at the last history bar, the value
// [Core.CDLMATHOLD] writes there.
//
// inOpen, inHigh, inLow and inClose are the histories, of one length; the
// parameters are those of [Core.CDLMATHOLD].
//
// The error is [InsufficientHistory] for a history of at most
// [Core.CDLMATHOLDLookback] bars, [OutOfRangeEndIndex] for one longer than
// [IndexMax]+1 bars, and [BadParam] for a parameter out of range or histories
// of different lengths.
func (c *Core) CDLMATHOLDOpen(inOpen, inHigh, inLow, inClose []float64, optInPenetration float64) (*CDLMATHOLDStream, int32, error) {
	sp, err := c.cdlmatholdOpenInternal(inOpen, inHigh, inLow, inClose, 0, optInPenetration)
	if err != nil {
		return nil, 0, err
	}
	return sp, sp.cur_outInteger, nil
}

// CDLMATHOLDOpenAndFill opens a stream as [Core.CDLMATHOLDOpen] does and also
// writes the outputs over the whole history, as [Core.CDLMATHOLD] writes them
// for bars 0 through len(inOpen)-1, returning that range.
//
// Each output must hold len(inOpen) minus [Core.CDLMATHOLDLookback] values and
// share no memory with an input or another output.
//
// The errors are those of [Core.CDLMATHOLDOpen], and [BadParam] for an output
// that is empty, too short or sharing memory.
func (c *Core) CDLMATHOLDOpenAndFill(inOpen, inHigh, inLow, inClose []float64, optInPenetration float64, outInteger []int32) (*CDLMATHOLDStream, OutRange, error) {
	if len(inOpen) > IndexMax+1 {
		return nil, OutRange{}, OutOfRangeEndIndex
	}
	lookback := int(c.cdlmatholdLookback(optInPenetration))
	if lookback < 0 {
		return nil, OutRange{}, BadParam
	}
	if len(inHigh) != len(inOpen) {
		return nil, OutRange{}, BadParam
	}
	if len(inLow) != len(inOpen) {
		return nil, OutRange{}, BadParam
	}
	if len(inClose) != len(inOpen) {
		return nil, OutRange{}, BadParam
	}
	outLen := max(len(inOpen)-lookback, 0)
	if len(outInteger) == 0 || len(outInteger) < outLen {
		return nil, OutRange{}, BadParam
	}
	var outBegIdx, outNBElement int32
	sp, err := c.cdlmatholdOpenAndFillInternal(inOpen, inHigh, inLow, inClose, 0, optInPenetration, &outBegIdx, &outNBElement, outInteger)
	if err != nil {
		return nil, OutRange{}, err
	}
	return sp, OutRange{BegIdx: int(outBegIdx), NBElement: int(outNBElement)}, nil
}
